{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Golidocitinib showed >80% oral bioavailability in healthy participants based on a radiolabeled mass balance study, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brexpiprazole has a reported absolute oral bioavailability of 95% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "GSK1322322 showed 77% absolute oral bioavailability after a meal in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "GSK1322322 showed 57% absolute oral bioavailability in the fasted state in healthy volunteers, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Brigatinib oral bioavailability was approximately 46% in healthy volunteers, supporting high oral bioavailability relative to the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Alisertib had a model-estimated bioavailability of 0.671 in pediatric patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "CC-292 demonstrated excellent oral bioavailability in a human Phase IA study, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "All available experimental records report oral bioavailability values above the 20% threshold, so high bioavailability is better supported. However, the query itself was not directly measured and structural similarity to the retrieved analogues is not visible, making transferability uncertain.",
  "evidence_gaps": [
    "No direct experimental measurement of oral bioavailability for the query molecule.",
    "Query structure and physicochemical prior are not provided, so similarity to the retrieved analogues cannot be assessed.",
    "Some records report bioavailability type as unspecified rather than absolute, adding uncertainty to endpoint matching."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

